@@ -0,0 +1,26 @@
+import fs from 'node:fs';
+import path from 'node:path';
+import Module from 'node:module';
+import ts from 'typescript';
+import { Plugin, PluginFactory } from './plugin';
+
+interface Config { plugins?: PluginFactory[] }
+
+function loadModule(file: string): Config {
+  const source = fs.readFileSync(file, 'utf8');
+  const compiled = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2020, esModuleInterop: true } }).outputText;
+  const loaded = new Module(file, module);
+  loaded.filename = file;
+  loaded.paths = Module._nodeModulePaths(path.dirname(file));
+  (loaded as Module & { _compile(code: string, filename: string): void })._compile(compiled, file);
+  return (loaded.exports.default || loaded.exports) as Config;
+}
+
+export async function loadConfiguredPlugins(configFile = 'ssg.config.ts'): Promise<Plugin[]> {
+  const file = path.resolve(configFile);
+  if (!fs.existsSync(file)) return [];
+  const config = loadModule(file);
+  const result: Plugin[] = [];
+  for (const factory of config.plugins || []) result.push(typeof factory === 'function' ? await factory({} as never) : factory);
+  return result;
+}

